import unittest

from hourglass.models import Span
from hourglass.rounding import round_span, rounded_labels


class RoundingTests(unittest.TestCase):
    def test_when_times_are_already_on_the_step(self):
        self.assertEqual(
            rounded_labels([Span(540, 1035)], 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_when_times_are_off_the_step(self):
        self.assertEqual(round_span(Span(542, 1030), 15), Span(540, 1035))

    def test_when_time_is_exactly_halfway(self):
        self.assertEqual(round_span(Span(547, 600), 15), Span(540, 600))
        self.assertEqual(round_span(Span(548, 600), 15), Span(555, 600))

    def test_when_end_rounds_up_to_midnight(self):
        self.assertEqual(round_span(Span(1000, 1438), 5), Span(1000, 1440))

    def test_when_there_are_several_spans(self):
        self.assertEqual(
            rounded_labels([Span(481, 721), Span(780, 1020)], 30),
            ["08:00-12:00 (4h 0m)", "13:00-17:00 (4h 0m)"],
        )

    def test_when_there_are_no_spans(self):
        self.assertEqual(rounded_labels([], 15), [])

    def test_when_step_is_zero(self):
        with self.assertRaises(ValueError):
            rounded_labels([Span(0, 60)], 0)

    def test_when_step_is_negative(self):
        with self.assertRaises(ValueError):
            rounded_labels([Span(0, 60)], -15)

    def test_when_step_does_not_divide_an_hour(self):
        with self.assertRaises(ValueError):
            rounded_labels([Span(0, 60)], 7)

    def test_when_step_is_bad_and_no_spans_given(self):
        with self.assertRaises(ValueError):
            rounded_labels([], 7)

    def test_when_span_collapses_to_nothing(self):
        with self.assertRaises(ValueError):
            round_span(Span(541, 543), 15)


if __name__ == "__main__":
    unittest.main()
